import {db} from "./database";
import {type AgentPlanItem, type AgentResponseItem, type AgentRunOutput, MODEL_STEPS_PER_SEGMENT} from "@/domain/agent";
import {decodeResponseOutput, toResponseInput} from "@/lib/ai/responsesStream";
import {validateTaskPlan} from "@/lib/agent/taskState";
import {targetRevision} from "@/lib/productionRevision";
import {toolNamesForCall} from "@/domain/agentToolSelection";
import {buildFinishingCheckPrompt} from "@/lib/agent/finishingCheck";
import {nowIso} from "@/lib/ids";

function parsePlan(raw: unknown): AgentPlanItem[] | undefined {
    try {
        if (!Array.isArray(raw)) return;
        const parsed = validateTaskPlan(raw);
        if (targetRevision(raw) !== targetRevision(parsed)) return;
        return parsed;
    } catch {
        return;
    }
}

/** Saves a single local finishing checkpoint at a successful no-tool boundary.
 * Does not complete the run, force tools, change permissions or perform network work.
 */
export async function saveAgentFinishingCheck(
    runId: string, expectedStep: number, output: AgentRunOutput, responseOutput?: AgentResponseItem[], signal?: AbortSignal,
): Promise<boolean> {
    return db.transaction("rw", [db.agentRuns, db.agentToolCalls, db.chatThreads, db.chatMessages, db.projects, db.agentTasks], async () => {
        signal?.throwIfAborted();
        const run = await db.agentRuns.get(runId);
        if (!run || run.status !== "running" || run.finishingCheck || run.interactionMode === "conversation" || !run.enabledToolNames?.length ||
            !Number.isSafeInteger(expectedStep) || expectedStep < 1 || run.modelStep !== expectedStep ||
            expectedStep - (run.modelStepSegmentStart ?? 0) >= MODEL_STEPS_PER_SEGMENT) return false;
        const thread = await db.chatThreads.get(run.threadId),
            message = await db.chatMessages.get(run.assistantMessageId);
        if (!thread || thread.projectId !== run.projectId || !message || message.threadId !== thread.id || message.runId !== run.id ||
            run.projectId && !await db.projects.get(run.projectId)) throw new Error("收尾检查的执行或项目归属已变化");
        if (run.taskId) {
            const task = await db.agentTasks.get(run.taskId);
            if (!task || task.threadId !== thread.id || task.projectId !== run.projectId || task.lifecycle !== "open") return false;
        }
        const siblings = await db.agentRuns.where("threadId").equals(thread.id).toArray();
        const history = await db.chatMessages.where("threadId").equals(thread.id).toArray();
        if (siblings.some(row => row.id !== runId && row.createdAt >= run.createdAt) || history.some(row => row.role === "user" && row.createdAt > run.createdAt)) return false;
        const plan = parsePlan(run.plan);
        if (!plan?.some(item => item.status !== "completed")) return false;
        const calls = (await db.agentToolCalls.where("runId").equals(runId).toArray()).sort((a, b) => a.step - b.step || a.order - b.order);
        if (!calls.length || calls.some(call => call.threadId !== run.threadId || call.status !== "completed" || call.step >= expectedStep)) return false;
        const saved = calls.filter(call => call.name === "update_run_plan").at(-1);
        if (!saved?.atomic || saved.effect !== "bookkeeping" || !saved.result || saved.result.length > 65536 ||
            !toolNamesForCall(run, saved.step).includes("update_run_plan")) return false;
        try {
            const result = JSON.parse(saved.result);
            const written = parsePlan(result.plan);
            const requested = parsePlan(JSON.parse(saved.arguments).steps);
            if (!written || !requested || targetRevision(written) !== targetRevision(plan) || targetRevision(requested) !== targetRevision(plan)) return false;
        } catch {
            return false;
        }
        if (typeof output.content !== "string" || output.content.length > 4_194_304 || typeof (output.reasoning ?? "") !== "string" || (output.reasoning?.length ?? 0) > 4_194_304 ||
            output.reasoningDurationMs !== undefined && (!Number.isFinite(output.reasoningDurationMs) || output.reasoningDurationMs < 0)) throw new Error("收尾回复内容无效或超出限制");
        let responseItems: AgentResponseItem[] | undefined;
        if (run.protocol === "responses") {
            const decoded = decodeResponseOutput(responseOutput, []);
            if (!decoded.items.length || decoded.calls.length || decoded.content !== output.content || decoded.reasoning !== (output.reasoning ?? "")) throw new Error("Responses 收尾信封不完整或与公开回复不匹配");
            if (targetRevision(decoded.items) !== targetRevision(responseOutput)) throw new Error("Responses 收尾信封包含未验证内容");
            // Keep opaque reasoning and item identity exactly as the validated transport returned.
            responseItems = responseOutput;
        } else if (responseOutput !== undefined) throw new Error("收尾检查协议与回复信封不匹配");
        const notice = {role: "system" as const, content: buildFinishingCheckPrompt(run, calls)};
        const previous = run.continuationMessages ?? run.requestMessages;
        const at = nowIso();
        signal?.throwIfAborted();
        await db.agentRuns.update(run.id, {
            finishingCheck: {step: expectedStep, createdAt: at},
            activitySteps: [...(run.activitySteps ?? []), {
                step: expectedStep,
                content: output.content,
                reasoning: output.reasoning,
                reasoningDurationMs: output.reasoningDurationMs
            }],
            continuationMessages: [...previous, {role: "assistant", content: output.content}, notice],
            ...(responseItems ? {responseItems: [...(run.responseItems ?? toResponseInput(previous)), ...responseItems, ...toResponseInput([notice])]} : {}),
            updatedAt: at,
        });
        signal?.throwIfAborted();
        return true;
    });
}

import {db} from './database';
import {AtomicToolRollbackError, executeAtomicTool} from './agentTools';
import {resolveConnector, setCharacterSlot, setPropSlot, setSceneSlot, setShotSlot, setStyleSlot} from './repo';
import type {AgentGenerationJob} from '@/domain/agentGeneration';
import {
    type GenerationBatch,
    type GenerationBatchItem,
    generationEntityKey,
    type GenerationSnapshot,
    generationTargetKey,
    validateBatchLimits
} from '@/domain/agentGenerationBatch';
import {type GenerationSubmitArgs, generationSubmitSchema} from '@/lib/agent/generationProfiles';
import {loadGenerationInputs, prepareGenerationSnapshot} from '@/lib/agent/generationPreparation';
import {readGenerationTarget} from './agentGenerationTarget';
import {assertProjectToolScope} from '@/lib/agent/projectScope';
import type {AgentToolContext} from '@/lib/agent/tools';
import {createId, nowIso} from '@/lib/ids';
import {targetRevision} from '@/lib/productionRevision';
import {flushPendingDrafts} from '@/lib/debouncedDraft';

type Prepared = Awaited<ReturnType<typeof prepareGenerationSnapshot>>;
const terminal = (job: AgentGenerationJob) => ['downloaded', 'applied', 'conflict', 'failed'].includes(job.status);

export function frozenGeneration(prepared: Prepared): GenerationSnapshot {
    const {args, config, provider, request, current, inputs, fingerprint} = prepared;
    return {
        connectorId: config.id,
        provider,
        baseUrl: config.baseUrl,
        model: args.model,
        kind: request.kind,
        target: request.target,
        baseRevision: current.revision,
        sourceRevisions: [{kind: request.target.kind, id: request.target.entityId, revision: current.revision}],
        parameters: request.parameters,
        inputs,
        fingerprint
    };
}

async function recheck(prepared: Prepared) {
    const current = await readGenerationTarget(prepared.request.target);
    const config = await resolveConnector(prepared.config.id);
    if (current.revision !== prepared.current.revision || !config?.apiKey.trim() || config.baseUrl !== prepared.config.baseUrl || config.definitionId !== prepared.provider) throw new Error('目标或连接配置已变化，请重新检查');
    for (const record of prepared.records) {
        if (!record) throw new Error('输入素材已删除');
        const currentMedia = await db.media.get(record.id);
        if (!currentMedia || currentMedia.projectId !== record.projectId || currentMedia.mimeType !== record.mimeType || currentMedia.blob.size !== record.blob.size) throw new Error('输入素材已变化');
    }
}

export async function ownedGenerationBatch(id: string, threadId: string, mutate = true) {
    const batch = await db.agentGenerationBatches.get(id);
    if (!batch || batch.threadId !== threadId) throw new Error('批次不存在或不属于当前对话');
    const thread = await db.chatThreads.get(threadId), run = await db.agentRuns.get(batch.runId),
        call = await db.agentToolCalls.get(batch.originCallId);
    if (!thread || !run || run.threadId !== threadId || run.projectId !== thread.projectId || run.projectId && run.projectId !== batch.projectId || !call || call.runId !== run.id || call.threadId !== threadId || call.name !== 'prepare_generation_batch') throw new Error('批次来源或项目归属已失效');
    if (batch.projectId !== 'studio' && !await db.projects.get(batch.projectId)) throw new Error('批次项目已删除');
    if (batch.taskId) {
        const task = await db.agentTasks.get(batch.taskId);
        if (!task || task.threadId !== threadId || run.taskId !== task.id || task.projectId !== run.projectId) throw new Error('批次任务来源已失效');
        if (mutate && task.lifecycle !== 'open') throw new Error('请先重新打开任务');
    }
    return batch;
}

const itemsFor = (batchId: string) => db.agentGenerationBatchItems.where('batchId').equals(batchId).sortBy('order');

export async function readGenerationBatch(id: string, threadId: string) {
    return db.transaction('r', db.tables, async () => {
        const batch = await ownedGenerationBatch(id, threadId, false);
        const items = await itemsFor(id), jobs = await db.agentGenerationJobs.where('batchId').equals(id).toArray();
        const currentMedia: Record<string, string | undefined> = {};
        for (const item of items) {
            try {
                currentMedia[item.targetKey] = (await readGenerationTarget(item.baseline.target)).slot.result?.mediaId;
            } catch {
                currentMedia[item.targetKey] = undefined;
            }
        }
        return {batch, items, jobs, currentMedia};
    });
}

export async function prepareGenerationBatch(title: string, candidates: GenerationSubmitArgs[], context: AgentToolContext) {
    try {
        return await prepareGenerationBatchDraft(title, candidates, context);
    } catch (error) {
        // Preparation never submits a remote request. Preflight failures happen before
        // the atomic batch/items/result write, and transaction failures roll it back.
        throw new AtomicToolRollbackError(error instanceof Error ? error.message : '批量草稿准备失败，未提交生成');
    }
}

async function prepareGenerationBatchDraft(title: string, candidates: GenerationSubmitArgs[], context: AgentToolContext) {
    const existing = await db.agentGenerationBatches.where('sourceCallId').equals(context.callId).first();
    if (existing) {
        await ownedGenerationBatch(existing.id, context.threadId, false);
        return batchDraftSummary(existing, await itemsFor(existing.id));
    }
    validateBatchLimits(candidates.map(draft => ({draft})));
    await assertProjectToolScope(context, 'prepare_generation_batch', {projectId: candidates[0].target.projectId}, true);
    const prepared: Prepared[] = [];
    for (const candidate of candidates) prepared.push(await prepareGenerationSnapshot(candidate, context.signal));
    return executeAtomicTool(context, async () => {
        for (const item of prepared) await recheck(item);
        const run = (await db.agentRuns.get(context.runId))!;
        const at = nowIso(), id = createId('genbatch');
        const items: GenerationBatchItem[] = prepared.map((value, order) => ({
            id: createId('candidate'),
            batchId: id,
            projectId: value.request.target.projectId,
            threadId: context.threadId,
            order,
            targetKey: generationTargetKey(value.request.target),
            label: value.current.label,
            proposal: value.args,
            draft: value.args,
            included: true,
            state: 'draft',
            baseline: frozenGeneration(value),
            createdAt: at,
            updatedAt: at
        }));
        const batch: GenerationBatch = {
            version: 1,
            id,
            projectId: items[0].projectId,
            threadId: context.threadId,
            runId: context.runId,
            sourceCallId: context.callId,
            originCallId: context.callId,
            taskId: run.taskId,
            title: title.trim().slice(0, 160) || '批量生成',
            revision: 1,
            status: 'draft',
            itemIds: items.map(i => i.id),
            confirmedItemIds: [],
            entityRevisions: {},
            selections: {},
            applications: [],
            createdAt: at,
            updatedAt: at
        };
        await db.agentGenerationBatches.add(batch);
        await db.agentGenerationBatchItems.bulkAdd(items);
        return batchDraftSummary(batch, items);
    });
}

function batchDraftSummary(batch: GenerationBatch, items: GenerationBatchItem[]) {
    return {
        batchId: batch.id,
        status: batch.status,
        targetCount: new Set(items.map(i => i.targetKey)).size,
        candidateCount: items.length,
        submitted: false
    };
}

function requireRevision(batch: GenerationBatch, revision: number) {
    if (batch.revision !== revision) throw new Error('批次已更新，请重新读取；当前编辑仍保留');
}

function immutableContext(draft: GenerationSubmitArgs, proposal: GenerationSubmitArgs) {
    if (targetRevision({target: draft.target, inputs: draft.inputs}) !== targetRevision({
        target: proposal.target,
        inputs: proposal.inputs
    })) throw new Error('目标和输入素材不能修改，请建立新提案');
}

async function writeBatch(batch: GenerationBatch, patch: Partial<GenerationBatch>) {
    const next = {...batch, ...patch, revision: batch.revision + 1, updatedAt: nowIso()};
    await db.agentGenerationBatches.put(next);
    return next;
}

/** Save all edited rows by CAS. Temporary empty prompts are valid drafts, never confirmed requests. */
export async function saveGenerationBatchDraft(id: string, threadId: string, revision: number, edits: Array<{
    id: string;
    draft: GenerationSubmitArgs;
    included: boolean
}>) {
    return db.transaction('rw', db.tables, async () => {
        const batch = await ownedGenerationBatch(id, threadId);
        requireRevision(batch, revision);
        if (batch.status !== 'draft') throw new Error('已确认的配置不能修改');
        const items = await itemsFor(id);
        if (edits.length !== items.length || new Set(edits.map(e => e.id)).size !== items.length) throw new Error('候选列表已变化');
        for (const item of items) {
            const edit = edits.find(e => e.id === item.id);
            if (!edit) throw new Error('候选列表已变化');
            // Parse structure with a placeholder while preserving unfinished prompt text.
            const parsed = generationSubmitSchema.parse({
                ...edit.draft,
                prompt: edit.draft.prompt.trim() ? edit.draft.prompt : '草稿'
            });
            parsed.prompt = edit.draft.prompt;
            immutableContext(parsed, item.proposal);
            await db.agentGenerationBatchItems.put({
                ...item,
                draft: parsed,
                included: edit.included,
                updatedAt: nowIso()
            });
        }
        return writeBatch(batch, {});
    });
}

export async function changeGenerationBatchItems(id: string, threadId: string, revision: number, itemId: string, action: 'clone' | 'remove') {
    return db.transaction('rw', db.tables, async () => {
        const batch = await ownedGenerationBatch(id, threadId);
        requireRevision(batch, revision);
        if (batch.status !== 'draft') throw new Error('只能编辑草稿候选');
        const items = await itemsFor(id), item = items.find(i => i.id === itemId);
        if (!item) throw new Error('候选不存在');
        if (action === 'remove') {
            if (items.length === 1) throw new Error('最后一份候选请使用放弃批次');
            await db.agentGenerationBatchItems.delete(item.id);
            return writeBatch(batch, {itemIds: batch.itemIds.filter(value => value !== item.id)});
        }
        validateBatchLimits([...items, item]);
        const clone = {
            ...item,
            id: createId('candidate'),
            order: Math.max(...items.map(i => i.order)) + 1,
            createdAt: nowIso(),
            updatedAt: nowIso()
        };
        await db.agentGenerationBatchItems.add(clone);
        return writeBatch(batch, {itemIds: [...batch.itemIds, clone.id]});
    });
}

export async function confirmGenerationBatch(id: string, threadId: string, revision: number, signal: AbortSignal) {
    const before = await readGenerationBatch(id, threadId);
    requireRevision(before.batch, revision);
    if (before.batch.status !== 'draft') throw new Error('批次已确认或放弃');
    const included = before.items.filter(i => i.included);
    validateBatchLimits(included);
    const prepared: Prepared[] = [];
    for (const item of included) {
        const value = await prepareGenerationSnapshot(item.draft, signal);
        if (value.current.revision !== item.baseline.baseRevision || targetRevision(value.inputs) !== targetRevision(item.baseline.inputs)) throw new Error('原目标或输入已变化，请重新准备批次');
        prepared.push(value);
    }
    return db.transaction('rw', db.tables, async () => {
        signal.throwIfAborted();
        const batch = await ownedGenerationBatch(id, threadId);
        requireRevision(batch, revision);
        if (batch.status !== 'draft') throw new Error('批次已确认或放弃');
        const revisions: Record<string, string> = {};
        for (const [index, item] of included.entries()) {
            await recheck(prepared[index]);
            const snapshot = frozenGeneration(prepared[index]);
            revisions[generationEntityKey(snapshot.target)] = snapshot.baseRevision;
            await db.agentGenerationBatchItems.put({...item, snapshot, state: 'queued', updatedAt: nowIso()});
        }
        for (const item of before.items.filter(i => !i.included)) await db.agentGenerationBatchItems.update(item.id, {state: 'cancelled'});
        return writeBatch(batch, {
            status: 'ready',
            confirmedAt: nowIso(),
            confirmedItemIds: included.map(i => i.id),
            entityRevisions: revisions
        });
    });
}

export async function controlGenerationBatch(id: string, threadId: string, action: 'pause' | 'cancel' | 'run', reason?: string) {
    return db.transaction('rw', db.tables, async () => {
        const batch = await ownedGenerationBatch(id, threadId);
        if (action === 'run' && (!batch.confirmedAt || batch.status === 'draft')) throw new Error('请先确认生成请求');
        if (action === 'run' && (await db.agentGenerationJobs.where('batchId').equals(id).toArray()).some(j => j.status === 'unknown')) {
            return writeBatch(batch, {
                status: 'paused',
                pauseReason: '提交结果未知；仅可继续查询其他已受理任务，请核实供应商记录'
            });
        }
        if (action === 'cancel') for (const item of await itemsFor(id)) if (!item.jobId) await db.agentGenerationBatchItems.update(item.id, {
            state: 'cancelled',
            updatedAt: nowIso()
        });
        return writeBatch(batch, {
            status: action === 'run' ? (batch.status === 'cancelled' ? 'cancelled' : 'running') : action === 'cancel' ? 'cancelled' : 'paused',
            pauseReason: reason
        });
    });
}

export async function assertBatchDispatch(job: AgentGenerationJob) {
    if (!job.batchId || !job.batchItemId) throw new Error('不是批次任务');
    const batch = await ownedGenerationBatch(job.batchId, job.threadId);
    const item = await db.agentGenerationBatchItems.get(job.batchItemId);
    if (batch.status !== 'running' || !item || item.jobId !== job.id || item.state !== 'claimed' || !batch.confirmedItemIds.includes(item.id) || !await db.agentGenerationJobs.get(job.id)) throw new Error('批次已暂停或取消，未再次提交');
    if ((await db.agentGenerationJobs.where('batchId').equals(batch.id).toArray()).some(j => j.status === 'unknown')) throw new Error('本批有未知提交，已暂停后续发送');
    if ((await readGenerationTarget(job.target)).revision !== batch.entityRevisions[generationEntityKey(job.target)]) throw new Error('目标已被修改，尚未付费提交');
}

export async function claimBatchItem(id: string, threadId: string, itemId: string): Promise<AgentGenerationJob | undefined> {
    return db.transaction('rw', db.tables, async () => {
        const batch = await ownedGenerationBatch(id, threadId);
        if (batch.status !== 'running') return;
        const jobs = await db.agentGenerationJobs.where('batchId').equals(id).toArray();
        if (jobs.some(j => j.status === 'unknown')) {
            await writeBatch(batch, {status: 'paused', pauseReason: '提交结果未知，请核实供应商记录'});
            return;
        }
        const item = await db.agentGenerationBatchItems.get(itemId);
        if (!item || item.batchId !== id || item.jobId || item.state !== 'queued' || !item.snapshot || !batch.confirmedItemIds.includes(item.id)) return;
        const duplicates = await db.agentGenerationJobs.where('fingerprint').equals(item.snapshot.fingerprint).toArray();
        if (duplicates.some(j => !terminal(j) && (j.batchId !== id || j.status === 'unknown'))) throw new Error('相同请求仍在其他任务处理中，不能重复提交');
        const at = nowIso();
        const job: AgentGenerationJob = {
            ...item.snapshot,
            version: 1,
            id: createId('genjob'),
            batchId: id,
            batchItemId: item.id,
            runId: batch.runId,
            threadId,
            projectId: batch.projectId,
            status: 'submitting',
            createdAt: at,
            updatedAt: at
        };
        await db.agentGenerationJobs.add(job);
        await db.agentGenerationBatchItems.put({...item, jobId: job.id, state: 'claimed', updatedAt: at});
        await assertBatchDispatch(job);
        return job;
    });
}

export async function settleGenerationBatch(id: string, threadId: string) {
    return db.transaction('rw', db.tables, async () => {
        const batch = await ownedGenerationBatch(id, threadId), items = await itemsFor(id),
            jobs = await db.agentGenerationJobs.where('batchId').equals(id).toArray();
        if (batch.status === 'cancelled') return batch;
        const pending = items.some(i => i.state === 'queued') || jobs.some(j => !terminal(j));
        return writeBatch(batch, {
            status: pending ? 'paused' : 'settled',
            pauseReason: pending ? batch.pauseReason ?? '本地等待已暂停；继续时只恢复已有任务和未发送候选' : undefined
        });
    });
}

export async function selectBatchCandidate(id: string, threadId: string, itemId: string) {
    return db.transaction('rw', db.tables, async () => {
        const batch = await ownedGenerationBatch(id, threadId), item = await db.agentGenerationBatchItems.get(itemId);
        const job = item?.jobId ? await db.agentGenerationJobs.get(item.jobId) : undefined;
        if (!item || item.batchId !== id || !job?.result || !terminal(job)) throw new Error('候选尚无本地结果');
        const media = await db.media.get(job.result.mediaId);
        if (!media || media.projectId !== batch.projectId || !media.blob.size || !media.mimeType.startsWith(`${job.kind}/`)) throw new Error('候选素材不可用');
        return writeBatch(batch, {selections: {...batch.selections, [item.targetKey]: item.id}});
    });
}

/** Explicit user selection writes are grouped by entity. Other entities can succeed independently. */
export async function applyBatchSelections(id: string, threadId: string) {
    const before = await readGenerationBatch(id, threadId);
    await flushPendingDrafts(before.batch.projectId);
    const chosen = before.items.filter(i => before.batch.selections[i.targetKey] === i.id);
    const groups = new Map<string, GenerationBatchItem[]>();
    for (const item of chosen) {
        const key = generationEntityKey(item.baseline.target);
        groups.set(key, [...groups.get(key) ?? [], item]);
    }
    const outcomes: Array<{ targetKey: string; applied: boolean; error?: string }> = [];
    for (const [key, items] of groups) {
        try {
            const inputRecords: Awaited<ReturnType<typeof loadGenerationInputs>> = [];
            for (const item of items) {
                const job = await db.agentGenerationJobs.get(item.jobId!);
                if (!job?.result) throw new Error('候选结果不可用');
                inputRecords.push(...await loadGenerationInputs(job));
            }
            await db.transaction('rw', db.tables, async () => {
                let batch = await ownedGenerationBatch(id, threadId);
                for (const record of inputRecords) {
                    const saved = await db.media.get(record.id);
                    if (!saved || saved.projectId !== record.projectId || saved.mimeType !== record.mimeType || saved.blob.size !== record.blob.size) throw new Error('输入素材已变化，未写入结果');
                }
                const current = await readGenerationTarget(items[0].baseline.target);
                if (current.revision !== batch.entityRevisions[key]) throw new Error('目标已被人工修改；结果保留，未覆盖');
                for (const item of items) {
                    if (batch.selections[item.targetKey] !== item.id) throw new Error('所选候选已变化，请重新检查');
                    const job = await db.agentGenerationJobs.get(item.jobId!);
                    if (!job?.result || job.batchId !== id || job.batchItemId !== item.id) throw new Error('候选记录已变化');
                    const media = await db.media.get(job.result.mediaId);
                    if (!media || media.projectId !== job.projectId || !media.blob.size || !media.mimeType.startsWith(`${job.kind}/`)) throw new Error('结果素材不可用');
                    const target = await readGenerationTarget(job.target);
                    if (target.slot.result?.mediaId === job.result.mediaId) continue;
                    const slot = {...target.slot, result: job.result};
                    switch (job.target.kind) {
                        case 'shot':
                            await setShotSlot(job.target.entityId, job.target.slot!, slot);
                            break;
                        case 'character':
                            await setCharacterSlot(job.target.entityId, job.target.slot, slot);
                            break;
                        case 'scene':
                            await setSceneSlot(job.target.entityId, job.target.slot, slot);
                            break;
                        case 'prop':
                            await setPropSlot(job.target.entityId, job.target.slot, slot);
                            break;
                        case 'style':
                            await setStyleSlot(job.target.entityId, job.target.slot, slot);
                            break;
                    }
                    const after = await readGenerationTarget(job.target);
                    await db.agentGenerationJobs.update(job.id, {
                        status: 'applied',
                        error: undefined,
                        updatedAt: nowIso()
                    });
                    batch = await writeBatch(batch, {
                        entityRevisions: {...batch.entityRevisions, [key]: after.revision},
                        applications: [...batch.applications, {
                            itemId: item.id,
                            jobId: job.id,
                            targetKey: item.targetKey,
                            baseline: job.baseRevision,
                            beforeRevision: target.revision,
                            afterRevision: after.revision,
                            before: target.slot.result,
                            result: job.result,
                            at: nowIso(),
                        }]
                    });
                }
            });
            outcomes.push(...items.map(item => ({targetKey: item.targetKey, applied: true})));
        } catch (error) {
            outcomes.push(...items.map(item => ({
                targetKey: item.targetKey,
                applied: false,
                error: error instanceof Error ? error.message : '写入失败，结果保留'
            })));
        }
    }
    return outcomes;
}

export async function retryFailedBatch(id: string, threadId: string) {
    const before = await readGenerationBatch(id, threadId);
    const failures = before.items.filter(i => before.jobs.find(j => j.id === i.jobId)?.status === 'failed');
    if (!failures.length) throw new Error('没有明确失败的候选；未知提交不能重试');
    const prepared: Prepared[] = [];
    for (const item of failures) prepared.push(await prepareGenerationSnapshot(item.draft, new AbortController().signal));
    return db.transaction('rw', db.tables, async () => {
        const source = await ownedGenerationBatch(id, threadId);
        const at = nowIso(), nextId = createId('genbatch');
        for (const [index, item] of failures.entries()) {
            if ((await db.agentGenerationJobs.get(item.jobId!))?.status !== 'failed') throw new Error('失败状态已变化');
            await recheck(prepared[index]);
        }
        const items = failures.map((item, index): GenerationBatchItem => ({
            ...item,
            id: createId('candidate'),
            batchId: nextId,
            order: index,
            state: 'draft',
            included: true,
            jobId: undefined,
            snapshot: undefined,
            baseline: frozenGeneration(prepared[index]),
            createdAt: at,
            updatedAt: at
        }));
        const batch: GenerationBatch = {
            ...source,
            id: nextId,
            sourceCallId: undefined,
            title: `${source.title.slice(0, 150)} · 重试`,
            retrySourceBatchId: source.id,
            revision: 1,
            status: 'draft',
            itemIds: items.map(i => i.id),
            confirmedItemIds: [],
            confirmedAt: undefined,
            pauseReason: undefined,
            selections: {},
            entityRevisions: {},
            applications: [],
            createdAt: at,
            updatedAt: at
        };
        await db.agentGenerationBatches.add(batch);
        await db.agentGenerationBatchItems.bulkAdd(items);
        return batch;
    });
}

/** Call only while the caller holds this thread's Web Lock. Local reads/writes, no HTTP. */
export async function recoverAbandonedGenerationBatches(threadId: string) {
    await db.transaction('rw', db.tables, async () => {
        const batches = await db.agentGenerationBatches.where('threadId').equals(threadId).toArray();
        for (const batch of batches) {
            if (batch.status !== 'running') continue;
            for (const job of await db.agentGenerationJobs.where('batchId').equals(batch.id).toArray()) {
                if (job.status === 'submitting' && !job.providerTaskId) await db.agentGenerationJobs.update(job.id, {
                    status: 'unknown',
                    error: '上次提交结果未知，请核实供应商记录；不会自动重发',
                    updatedAt: nowIso()
                });
            }
            await writeBatch(batch, {status: 'paused', pauseReason: '上次本地执行已中断，继续前请检查各候选状态'});
        }
    });
}

import {db} from "./database";
import type {ProductionTarget} from "@/domain/production";
import type {GenerationSlot} from "@/domain/types";
import {emptySlot} from "@/domain/slot";
import {targetRevision} from "@/lib/productionRevision";

async function readTargetEntity(target: ProductionTarget) {
    switch (target.kind) {
        case "shot": return db.shots.get(target.entityId);
        case "character": return db.characters.get(target.entityId);
        case "scene": return db.scenes.get(target.entityId);
        case "prop": return db.props.get(target.entityId);
        default: return db.styles.get(target.entityId);
    }
}

type GenerationEntity = NonNullable<Awaited<ReturnType<typeof readTargetEntity>>>;

async function assertShotEpisode(target: Extract<ProductionTarget, {kind: "shot"}>, entity: GenerationEntity) {
    const episode = await db.episodes.get(target.episodeId);
    if (!episode || episode.projectId !== target.projectId || !("episodeId" in entity) || entity.episodeId !== target.episodeId) throw new Error("生成目标不属于当前故事");
}

/** Reads the current owned target inside the caller's transaction, if any. */
export async function readGenerationTarget(target: ProductionTarget) {
    if (target.projectId !== "studio" && !await db.projects.get(target.projectId)) throw new Error("生成目标项目已删除");
    const entity = await readTargetEntity(target);
    if (!entity || entity.projectId !== target.projectId) throw new Error("生成目标不存在或归属不匹配");
    if (target.kind === "shot") await assertShotEpisode(target, entity);
    if (!target.slot) throw new Error("生成目标缺少素材槽位");
    let slot: GenerationSlot;
    if ("slots" in entity) {
        const slots: Partial<Record<string, GenerationSlot>> = entity.slots;
        slot = slots[target.slot] ?? emptySlot();
    } else if (target.kind === "shot") slot = entity[target.slot];
    else slot = emptySlot();
    return {
        entity,
        slot,
        revision: targetRevision(entity),
        label: "name" in entity ? entity.name : `镜头 ${entity.shotNumber || entity.order + 1}`
    };
}

import {db} from "./database";
import {nowIso} from "@/lib/ids";
import {MAX_LOADED_TOOLS, toolNamesForCall} from "@/domain/agentToolSelection";
import type {AgentToolContext} from "@/lib/agent/tools";
import {getProjectKind} from "@/domain/types";

/** Narrow exception for a project created by this run; never changes an existing binding. Caller owns transaction. */
export async function assertAgentProjectCreation(context: AgentToolContext, continuing: boolean, executing = false) {
    context.signal.throwIfAborted();
    const run = await db.agentRuns.get(context.runId), thread = await db.chatThreads.get(context.threadId);
    if (!run || !thread || run.threadId !== thread.id || run.status !== "running") throw new Error("执行已停止或归属不匹配");
    if (run.projectId || thread.projectId || run.createdProjectBinding || context.projectId) throw new Error("项目绑定对话不能创建其他项目，请在项目页新建");
    if (run.taskId || run.taskMode || thread.taskMode || run.interactionMode === "conversation") throw new Error("只有普通智能对话可以创建并继续项目");
    if (!run.enabledToolNames?.includes("project_create")) throw new Error("此执行未启用创建项目工具");
    const call = await db.agentToolCalls.get(context.callId);
    if (executing && (!call || call.name !== "project_create" || call.runId !== run.id || call.threadId !== thread.id || call.effect !== "write" || !call.atomic || call.status !== "running" ||
        !toolNamesForCall(run, call.step).includes("project_create") || ((run.permissionMode ?? "ask") === "ask" && call.decision !== "approve"))) throw new Error("创建项目工具尚未得到有效批准或归属不匹配");
    const message = await db.chatMessages.get(run.assistantMessageId);
    if (!message || message.threadId !== thread.id || message.runId !== run.id) throw new Error("执行消息归属不匹配");
    const history = await db.chatMessages.where("threadId").equals(thread.id).toArray();
    const runs = await db.agentRuns.where("threadId").equals(thread.id).toArray();
    if (runs.some(row => row.id !== run.id && row.createdAt >= run.createdAt) || history.some(row => row.role === "user" && row.createdAt > run.createdAt)) throw new Error("只能在当前最后一次执行创建项目");
    if (continuing) {
        const inputs = [...run.requestMessages, ...(run.continuationMessages ?? []), ...(run.responseItems ?? []), ...(run.context?.baseMessages ?? [])];
        if (inputs.some(row => row.referenceInput !== undefined) || run.context?.selectedReferences || run.referenceAudit?.some(row => row.inputs.length)) {
            throw new Error("当前执行包含绑定原归属的参考资料，不能自动切换项目。请使用 continueInProject=false 仅创建项目，再从结果入口开启项目对话；参考资料的归属保持不变。");
        }
        const calls = await db.agentToolCalls.where("runId").equals(run.id).toArray();
        // Same-envelope reads have completed but appendToolResults has not copied
        // their reference inputs into continuation yet.
        if (calls.some(row => {
            if (row.id === context.callId || row.status !== "completed" || !row.result) return false;
            try {
                return JSON.parse(row.result)?.referenceInput !== undefined;
            } catch {
                return false;
            }
        })) throw new Error("本轮已读取绑定原归属的参考资料，请使用 continueInProject=false 仅创建，再从结果入口开启项目对话。");
        if (calls.some(row => row.id !== context.callId && (row.status === "unknown" || row.status === "running" || row.effect === "write" && row.status === "completed"))) {
            throw new Error("当前执行已有其他归属的写入或未核实操作，不能自动绑定新项目。请使用 continueInProject=false 仅创建项目，再从结果入口继续。");
        }
        if (await db.agentGenerationJobs.where("threadId").equals(thread.id).count() || await db.agentGenerationBatches.where("threadId").equals(thread.id).count() ||
            (await db.audioGenerationJobs.toArray()).some(job => {
                const source = job.source;
                return source.kind === "agent" && runs.some(prior => prior.id === source.runId);
            })) {
            throw new Error("当前执行已有生成任务或批次，不能更换它们的项目归属。请使用 continueInProject=false 仅创建，再从结果入口继续。");
        }
    }
    return run;
}

export async function bindCreatedAgentProject(context: AgentToolContext, projectId: string): Promise<void> {
    const run = await assertAgentProjectCreation(context, true, true);
    const project = await db.projects.get(projectId);
    if (!project) throw new Error("刚创建的项目不存在");
    const preferred = getProjectKind(project) === "audio" ? "audio-production" : getProjectKind(project) === "music" ? "music-creation" : undefined;
    const state = run.toolLoading, group = state?.groups.find(row => row.id === preferred);
    const allowed = group?.toolNames.filter(name => run.enabledToolNames?.includes(name)) ?? [];
    const toolLoading = state && group && new Set([...state.foundationToolNames, ...allowed]).size <= MAX_LOADED_TOOLS
        ? {...state, loadedGroupIds: [group.id], loadedToolNames: [...new Set(allowed)]} : state;
    const at = nowIso();
    await db.chatThreads.update(run.threadId, {projectId, updatedAt: at});
    await db.agentRuns.update(run.id, {
        projectId,
        createdProjectBinding: {projectId, callId: context.callId},
        toolLoading,
        updatedAt: at
    });
}

import {inspectTaskGenerationOutput, ownedTaskGenerationJob, PICTURE_GENERATION_TOOLS, provesCompletedGeneration, taskGenerationToolSource} from "./taskGenerationEvidence";
import {db} from "./database";
import {editableAgentTask} from "./agentTaskGuards";
import type {AgentTaskRecord, TaskRecordInput, TaskRecordSource} from "@/domain/agentTaskRecords";
import {TASK_RECORD_CLAIMS, TASK_RECORD_KINDS} from "@/domain/agentTaskRecords";
import type {AgentTask, AgentToolCall} from "@/domain/agent";
import {createId, nowIso} from "@/lib/ids";
import {
    ownedTaskAudioGenerationJob,
    SOUND_GENERATION_TOOLS,
    taskAudioGenerationSource,
    taskAudioToolSource
} from "./taskAudioGenerationEvidence";

export async function listTaskRecords(taskId: string): Promise<AgentTaskRecord[]> {
    return db.agentTaskRecords.where("taskId").equals(taskId).sortBy("updatedAt");
}

export async function listTaskRecordVersions(taskId: string, recordId: string) {
    const record = await db.agentTaskRecords.get(recordId);
    if (!record || record.taskId !== taskId) throw new Error("记录不属于当前任务");
    return db.agentTaskRecordVersions.where("recordId").equals(recordId).sortBy("revision");
}

/** A completed ledger entry may describe a failed remote job or an apply conflict. */
export function provesCompletedEffect(call: AgentToolCall): boolean {
    if ((PICTURE_GENERATION_TOOLS as readonly string[]).includes(call.name)) return provesCompletedGeneration(call);
    let value: unknown;
    try {
        value = JSON.parse(call.result ?? "null");
    } catch {
        return false;
    }
    if (!value || typeof value !== "object" || Array.isArray(value)) return false;
    const result = value as Record<string, unknown>;
    if (result.error || result.ok === false || result.success === false) return false;
    // Other network tools can report a check without producing a business result.
    return call.effect === "write" && result.applied !== false;
}

export async function validateTaskSources(task: Pick<AgentTask, "id" | "threadId">, sources: TaskRecordSource[], claim: TaskRecordInput["claim"], author: "ai" | "user") {
    if (!Array.isArray(sources) || sources.length > 12) throw new Error("来源最多 12 项");
    let userEvidence = false, completedEffect = false;
    for (const source of sources) {
        if (!source.id || source.id.length > 120) throw new Error("来源标识无效");
        if (source.type === "message") {
            const message = await db.chatMessages.get(source.id);
            if (!message || message.threadId !== task.threadId || message.role !== "user" || (!message.content.trim() && !message.attachments?.length)) throw new Error("只能引用当前对话真实的用户消息");
            userEvidence = true;
        } else if (source.type === "tool") {
            const call = await db.agentToolCalls.get(source.id);
            const run = call && await db.agentRuns.get(call.runId);
            if (!call || !run || call.threadId !== task.threadId || run.threadId !== task.threadId || run.taskId !== task.id || call.status !== "completed" || !call.result || call.effect === "bookkeeping") throw new Error("来源不是当前任务已完成的业务工具结果");
            if ((SOUND_GENERATION_TOOLS as readonly string[]).includes(call.name)) {
                const evidence = await taskAudioToolSource(task, call);
                completedEffect ||= evidence?.supportsResult === true;
            } else if ((PICTURE_GENERATION_TOOLS as readonly string[]).includes(call.name)) {
                const evidence = await Promise.resolve(taskGenerationToolSource(task, call));
                completedEffect ||= evidence?.supportsResult === true;
            } else completedEffect ||= provesCompletedEffect(call);
        } else if (source.type === "generation") {
            const evidence = await taskGenerationSource(task, source.id);
            completedEffect ||= evidence.supportsResult;
        } else throw new Error("来源类型无效");
    }
    if (author === "ai" && claim === "decision" && !userEvidence) throw new Error("确认决策必须引用用户消息");
    if (author === "ai" && claim === "result" && !completedEffect) throw new Error("完成结果必须引用已完成的实际业务操作");
    if (author === "ai" && claim === "observation" && sources.length === 0) throw new Error("调研观察必须附真实来源；未核实内容请记为方案或待解决问题");
}

/** Transaction-internal write, shared by guarded manual saves and ledger-atomic tools. */
export async function writeTaskRecord(task: AgentTask, input: TaskRecordInput, options: {
    id?: string;
    expectedRevision?: number;
    author: "user" | "ai";
    runId?: string;
    requirementSnapshot?: boolean
}): Promise<AgentTaskRecord> {
    if (task.lifecycle !== "open") throw new Error("请先重新打开任务");
    if (!TASK_RECORD_KINDS.includes(input.kind) || !TASK_RECORD_CLAIMS.includes(input.claim) || !input.title.trim() || input.title.length > 120 || !input.body.trim() || input.body.length > (options.requirementSnapshot ? 100_000 : 12_000)) throw new Error("记录类型或内容无效：标题最多 120 字，正文最多 12,000 字");
    if (input.todoId && !task.plan.some((item) => item.id === input.todoId)) throw new Error("关联 Todo 不存在");
    await validateTaskSources(task, input.sources, input.claim, options.author);
    const existing = options.id ? await db.agentTaskRecords.get(options.id) : undefined;
    if (options.id && (!existing || existing.taskId !== task.id)) throw new Error("记录不属于当前任务");
    if (existing && options.expectedRevision !== existing.revision) throw new Error("记录已更新，请重新读取后修改");
    if (!existing && options.expectedRevision !== undefined) throw new Error("新记录不应指定旧版本");
    if (!existing && options.runId) {
        const duplicate = (await listTaskRecords(task.id)).find((record) => record.runId === options.runId && record.author === options.author && record.kind === input.kind && record.claim === input.claim && record.title === input.title.trim() && record.body === input.body.trim() && record.todoId === input.todoId && JSON.stringify(record.sources) === JSON.stringify(input.sources));
        if (duplicate) return duplicate;
    }
    const at = nowIso();
    const record: AgentTaskRecord = {
        ...input,
        title: input.title.trim(),
        body: input.body.trim(),
        id: existing?.id ?? createId("trec"),
        taskId: task.id,
        revision: (existing?.revision ?? 0) + 1,
        author: options.author,
        runId: options.runId,
        createdAt: existing?.createdAt ?? at,
        updatedAt: at
    };
    await db.agentTaskRecords.put(record);
    await db.agentTaskRecordVersions.add({
        ...record,
        recordId: record.id,
        versionId: `${record.id}:${record.revision}`
    });
    await db.agentTasks.update(task.id, {updatedAt: at});
    return record;
}

export async function saveTaskRecord(taskId: string, input: TaskRecordInput, options: {
    id?: string;
    expectedRevision?: number
} = {}): Promise<AgentTaskRecord> {
    return db.transaction("rw", db.tables, async () => writeTaskRecord(await editableAgentTask(taskId), input, {
        ...options,
        author: "user"
    }));
}

/** Genuine generation evidence is owned by the task and reflects current local media/slot state. */
export async function taskGenerationSource(task: Pick<AgentTask, "id" | "threadId">, jobId: string) {
    const soundJob = await db.audioGenerationJobs.get(jobId);
    if (soundJob) return taskAudioGenerationSource(task, soundJob);
    const job = await db.agentGenerationJobs.get(jobId);
    if (!job || !job.batchId || !await Promise.resolve(ownedTaskGenerationJob(task, job))) throw new Error("生成结果不属于当前任务批次");
    const {available, applied} = await Promise.resolve(inspectTaskGenerationOutput(job));
    return {
        id: job.id,
        batchId: job.batchId,
        status: job.status,
        result: job.result,
        label: `${job.kind === 'image' ? '图片' : '视频'} · ${job.model}`,
        available,
        applied,
        supportsResult: available,
        body: JSON.stringify({
            jobId: job.id,
            batchId: job.batchId,
            status: job.status,
            target: job.target,
            result: available ? job.result : undefined,
            available,
            applied,
            error: job.error
        })
    };
}

/** Shared source inventory; no remote refresh and no attribution to reading runs. */
export async function listTaskGenerationSources(task: AgentTask) {
    return db.transaction("r", db.tables, async () => {
        const sources: Awaited<ReturnType<typeof taskGenerationSource>>[] = [];
        const runs = await db.agentRuns.where("taskId").equals(task.id).toArray();
        const runIds = new Set(runs.filter(run => run.threadId === task.threadId).map(run => run.id));
        const jobs = await db.agentGenerationJobs.where("threadId").equals(task.threadId).toArray();
        for (const job of jobs.filter(job => job.batchId && runIds.has(job.runId))) {
            if (await Promise.resolve(ownedTaskGenerationJob(task, job))) sources.push(await Promise.resolve(taskGenerationSource(task, job.id)));
        }
        const soundJobs = await db.audioGenerationJobs.where("projectId").equals(task.projectId).toArray();
        for (const job of soundJobs) {
            if (await Promise.resolve(ownedTaskAudioGenerationJob(task, job))) sources.push(await Promise.resolve(taskAudioGenerationSource(task, job)));
        }
        return sources;
    });
}

